consignas.referencia:
void ponerEnCero(int *v, int n) {
  int i;

  for (i = 0; i < n; i++) {
    v[i] = 0;
  }
}

void duplicar(int v[], int n) {
  int i;

  for (i = 0; i < n; i++) {
    *(v + i) = *(v + i) * 2;
  }
}

int contarLetras(char *texto) {
  char *p = texto;
  int cantidad = 0;

  while (*p != '\0') {
    cantidad++;
    p++;
  }
  return cantidad;
}
